package android.hardware.usb;public class UsbDevice {public int vid=0x303a,pid=0x1001,id=7;public String name="/dev/bus/usb/001/002";public UsbInterface[] interfaces;public UsbDevice(UsbInterface...i){interfaces=i;}public int getVendorId(){return vid;}public int getProductId(){return pid;}public int getDeviceId(){return id;}public String getDeviceName(){return name;}public int getInterfaceCount(){return interfaces.length;}public UsbInterface getInterface(int i){return interfaces[i];}}
